#!/usr/bin/env python3
from pathlib import Path
import sys

if len(sys.argv) != 2:
    raise SystemExit('usage: transform_26565_v1_display_p3_fast_sr.py <candidate-root>')
ROOT = Path(sys.argv[1]).resolve()

def read(rel):
    return (ROOT/rel).read_text()

def write(rel, s):
    (ROOT/rel).write_text(s)

def replace_once(rel, old, new):
    s = read(rel)
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'{rel}: anchor count {n}, expected 1: {old[:140]!r}')
    write(rel, s.replace(old, new, 1))

